<template>
 <DrillingPageFrame title="防碰评价">
  <el-alert v-if="t.dataError.value" :title="t.dataError.value" type="warning" :closable="false" />
  <EngineeringWorkspace ref="workspace" task-type="anticollision" :title="t.title.value" :well-label="t.bore.value?t.label(t.bore.value):''" :datum="t.detail.value?.reference?.depth_datum" :trajectories="displayTrajectories" :has-result="!!displayNetwork" :nearest-pair="nearestPair" :risk-segments="displayNetwork?.risk_segments||[]" :risk-label="displayNetwork?.operational_risk_level" :minimum-sf="displayNetwork?.minimum_sf" :minimum-centerline-distance="displayNetwork?.min_distance" @save="t.save({scanStep})" @rename="t.rename" @history="t.showHistory" @export="t.exportReport($event?.format||'bundle',$event?.sections)" @refresh="t.loadBores">
   <template #input><el-collapse v-model="sections">
    <el-collapse-item title="井眼与数据版本" name="well"><el-form label-position="top"><el-form-item label="正钻井眼"><el-cascader v-model="t.borePath.value" :options="t.wellboreOptions.value" :props="{emitPath:true,checkStrictly:false}" :show-all-levels="true" filterable clearable placeholder="区块 / 井场 / 井 / 井眼" style="width:100%"/></el-form-item><el-form-item label="实钻测斜版本"><el-select v-model="t.versionId.value" @change="t.loadDetail"><el-option v-for="v in t.versions.value" :key="v.survey_version_id" :value="v.survey_version_id" :label="`v${v.version_no} · ${v.label||''}${Number(v.is_active)?'（当前）':''}`"/></el-select></el-form-item></el-form></el-collapse-item>
    <el-collapse-item title="参与扫描的邻井" name="neighbors">
      <NeighborSelector :field-id="t.fieldId.value" v-model="t.neighbors.value" @change="t.loadNeighborDetails" @save="t.saveNeighbors"/>
    </el-collapse-item>
    <el-collapse-item title="扫描设置" name="scan"><el-form label-position="top"><el-form-item label="最大扫描点间距（m）"><el-input-number v-model="scanStep" :min="0.1" :max="100" :step="0.5"/></el-form-item><el-form-item label="增量影响起点 MD（可选）"><el-input-number v-model="fromMd" :min="0" :controls="false" clearable/></el-form-item><el-form-item label="增量影响终点 MD（可选）"><el-input-number v-model="toMd" :min="0" :controls="false" clearable/></el-form-item></el-form><p class="hint">历史修订自动校验几何与协方差依赖；未变化井段复用，不依赖手填范围判断安全。</p><el-button type="primary" icon="Search" :loading="t.busy.value" :disabled="!referenceEligible||!t.detail.value" @click="scan">执行防碰扫描</el-button></el-collapse-item>
    <el-collapse-item title="误差模型与评价规则" name="rules"><el-descriptions :column="1" border><el-descriptions-item v-if="sfParameterKeys.includes('k')" label="不确定性放大系数 K">{{t.configForm.algorithmDefaults.errorModel.k}}</el-descriptions-item><el-descriptions-item label="轨道不确定性模型">{{errorModelName(t.configForm.algorithmDefaults.errorModel.modelVersion)}}</el-descriptions-item><el-descriptions-item label="分离系数计算公式">{{sfDetails.formula}}<p class="hint">{{sfDetails.definition}}</p></el-descriptions-item><el-descriptions-item label="评价方法">井间距法和分离系数法</el-descriptions-item><el-descriptions-item label="轨迹计算模型">最小曲率法</el-descriptions-item></el-descriptions><el-button link type="primary" @click="router.push('/drilling/basic/config?tab=errorModel')">修改工程配置</el-button></el-collapse-item>
   </el-collapse></template>
   <template #solutions><el-collapse :model-value="['summary','cache']"><el-collapse-item title="全井网结果" name="summary"><el-descriptions :column="1" border><el-descriptions-item label="状态">{{displayNetwork?.status||'未扫描'}}</el-descriptions-item><el-descriptions-item label="参与邻井">{{displayNetwork?.neighbor_count??'—'}}</el-descriptions-item><el-descriptions-item label="详细计算">{{displayNetwork?.candidate_count??'—'}}</el-descriptions-item><el-descriptions-item label="粗筛排除">{{displayNetwork?.prefiltered_count??'—'}}</el-descriptions-item><el-descriptions-item label="最小中心距">{{fmt(displayNetwork?.min_distance)}} m</el-descriptions-item><el-descriptions-item label="最小 SF">{{fmt(displayNetwork?.minimum_sf)}}</el-descriptions-item></el-descriptions></el-collapse-item><el-collapse-item title="增量计算记录" name="cache"><p>复用 {{displayNetwork?.incremental?.reused_blocks??0}} 块；重算 {{displayNetwork?.incremental?.recomputed_blocks??0}} 块</p><p class="hint">{{displayNetwork?.incremental?.dependency||'等待计算'}}</p></el-collapse-item></el-collapse></template>
   <template #collision><CollisionResults :network="displayNetwork" :neighbors="t.neighbors.value" :alarms="alarms" @acknowledge="ack" @resolve="resolve"/></template>
   <template #table><el-table :data="t.detail.value?.stations||[]" height="100%" border><el-table-column v-for="(label,key) in columns" :key="key" :prop="key" :label="label" min-width="110"/></el-table></template>
   <template #context><el-collapse :model-value="['source']"><el-collapse-item title="版本与来源" name="source"><el-descriptions :column="1" size="small"><el-descriptions-item label="实钻版本">{{t.versionId.value||'—'}}</el-descriptions-item><el-descriptions-item label="设计版本">{{t.design.value?.survey_version_id||'—'}}</el-descriptions-item><el-descriptions-item label="坐标系">{{coordinateReferenceLabel(t.detail.value?.reference)}}</el-descriptions-item><el-descriptions-item label="有效邻井">{{t.selectedNeighbors.value.length}}</el-descriptions-item></el-descriptions></el-collapse-item></el-collapse></template>
   <template #bottom><div class="rules">SF 红色 ≤ {{threshold.redSf}}；橙色 ≤ {{threshold.orangeSf}}；黄色 ≤ {{threshold.yellowSf}}；中心距红线 {{threshold.redDistance}} m。{{displayNetwork?.failed_pairs?.length?`${displayNetwork.failed_pairs.length} 个井对失败，评价不完整`:'两种评价同时执行'}}</div></template>
  </EngineeringWorkspace>
  <el-dialog v-model="t.historyOpen.value" title="防碰任务历史" width="85%" append-to-body><el-table :data="t.history.value" max-height="520" @row-dblclick="restore"><el-table-column prop="record_id" label="任务 ID"/><el-table-column prop="status" label="状态"/><el-table-column prop="title" label="任务"/><el-table-column prop="created_at" label="时间"/><el-table-column label="操作"><template #default="s"><el-button link @click="restore(s.row)">查看结果</el-button></template></el-table-column></el-table></el-dialog>
 </DrillingPageFrame>
</template>
<script setup>
import {computed,ref,watch} from 'vue'
import {coordinateReferenceLabel} from '@/utils/wellboreHierarchy'
import {useRouter} from 'vue-router'
import {ElMessage} from 'element-plus'
import {scanAntiCollisionNetwork,listCollisionAlarms,acknowledgeCollisionAlarm,resolveCollisionAlarm} from '@/api/drilling'
import DrillingPageFrame from '../../layout/DrillingPageFrame.vue'
import EngineeringWorkspace from '../../layout/EngineeringWorkspace.vue'
import NeighborSelector from '../../layout/NeighborSelector.vue'
import CollisionResults from '../../layout/CollisionResults.vue'
import {useTrajectoryTask} from '../../composables/useTrajectoryTask'
import {errorModelName,separationFactorDetails,separationFactorParameterKeys} from '@/utils/engineeringErrorModels'
const t=useTrajectoryTask('anticollision'),router=useRouter(),workspace=ref(),sections=ref(['well','neighbors','scan']),fromMd=ref(),toMd=ref(),alarms=ref([]),scanStep=ref(1)
const network=t.result,displayNetwork=network,displayTrajectories=t.baseTrajectories,threshold=computed(()=>t.configForm.algorithmDefaults.thresholds),nearestPair=computed(()=>displayNetwork.value?.nearest_pair?{reference:displayNetwork.value.nearest_pair.reference_point,neighbor:displayNetwork.value.nearest_pair.neighbor_point}:null)
const sfDetails=computed(()=>separationFactorDetails(t.configForm.algorithmDefaults.errorModel)),sfParameterKeys=computed(()=>separationFactorParameterKeys(t.configForm.algorithmDefaults.errorModel))
const referenceEligible=computed(()=>t.detail.value?.reference?.evaluation_eligibility!=='BLOCKED')
const columns={md:'MD（m）',inclination:'井斜（°）',azimuth:'网格方位（°）',tvd:'垂深（m）',north:'北坐标（m）',east:'东坐标（m）'},fmt=v=>v==null?'—':Number(v).toFixed(3)
watch(()=>t.configForm.algorithmDefaults.scanStep,v=>scanStep.value=v,{immediate:true})
async function scan(){const issue=t.inputIssue();if(issue){ElMessage.warning(issue);return}if(!t.selectedNeighbors.value.length){ElMessage.warning('请选择邻井');return}t.busy.value=true;try{network.value=await scanAntiCollisionNetwork({field_id:t.fieldId.value,...t.referencePayload(),step:scanStep.value,mode:'BOTH',error_model:t.errorModelPayload(),thresholds:t.thresholdsPayload(),incremental_from_md:fromMd.value??null,incremental_to_md:toMd.value??null});alarms.value=await listCollisionAlarms(t.fieldId.value,'ACTIVE');ElMessage[network.value.status==='COMPLETED'?'success':'warning'](network.value.status==='COMPLETED'?'防碰扫描完成':'部分井对计算失败，请查看详情')}catch(e){ElMessage.error(e.message||'扫描失败')}finally{t.busy.value=false}}
async function ack(row){await acknowledgeCollisionAlarm(row.alarm_id);alarms.value=await listCollisionAlarms(t.fieldId.value,'ACTIVE')}
async function resolve(row){await resolveCollisionAlarm(row.alarm_id);alarms.value=await listCollisionAlarms(t.fieldId.value,'ACTIVE')}
async function restore(row){const stored=await t.restoreHistory(row);if(stored){scanStep.value=stored.input.step??1;workspace.value.mode='collision'}}
</script>
<style scoped>.el-select,.el-input-number{width:100%}.hint{font-size:12px;color:var(--el-text-color-secondary);line-height:1.6}.rules{padding:0 14px 10px;font-size:12px}</style>
